<script lang="ts">
	import { Check, EthernetPort, RadioTower, Save, WifiOff } from '@lucide/svelte';
	import { onMount } from 'svelte';
	import FlatSelect from '$lib/components/FlatSelect.svelte';
	import type { DeviceConfig } from '$lib/device-config';
	import { getBmsModemConfig, getBmsModemStatus, hasBmsSession, listBmsNetworks, updateBmsModemConfig, updateBmsNetwork, type BmsNetwork } from '$lib/services/bms-api';
	import { getModem4GConfig, getModem4GStatus, getNetworkActualStatus, getNetworkConfigs, setModem4GConfig, setNetworkConfig, type Modem4GStatus, type NetworkConfig } from '$lib/services/rts-api';
	import { RTS_CARRIERS, buildBmsNetworkUpdateParams, normalizeBmsNetworkMode, type BmsNetworkForm, type ProductProfile, type RtsEthernetForm, type RtsModem4GForm } from '$lib/contracts/connectivity';

	let { config }: { config: DeviceConfig | null } = $props();
	let configuredProduct = $derived(config?.device.product ?? 'unified');
	let profile = $state<ProductProfile>('rts');
	let rtsTab = $state<'ethernet' | '4g'>('ethernet');
	let notice = $state('');
	let selectedCarrier = $state('Viettel');
	let ethernet = $state<RtsEthernetForm>({ isDhcp:true, ipAddress:'', subnetMask:'', gateway:'', dnsPrimary:'', dnsSecondary:'' });
	let rtsNetworks = $state<NetworkConfig[]>([]);
	let selectedRtsNetwork = $state<'eth0'|'eth1'>('eth1');
	let actualStatus = $state<Record<string,{ip:string;netmask:string;gateway:string}>>({});
	let modem = $state<RtsModem4GForm>({ enabled:true, apn:'v-internet', username:'', password:'' });
	let modemStatus = $state<Modem4GStatus>({status:'NO_MODEM',signalStrength:0,operator:'-',ipAddress:'-',connectionType:'-',modemModel:'-',imei:'-',lastError:null});
	let rtsError = $state('');
	let savingRts = $state(false);
	let bms = $state<BmsNetworkForm>({ id:'wan0', name:'WAN 0', interfaceName:'', available:false, connected:false, status:'UNAVAILABLE', ipAddress:'', subnetMask:'', gateway:'', dns:'', mode:'DHCP' });
	let bmsNetworks = $state<BmsNetwork[]>([]);
	let bmsNetworkError = $state('');
	let bmsModemError = $state('');
	let modemPasswordConfigured = $state(false);
	let savingBms = $state(false);
	let showProfileSwitch = $derived(configuredProduct === 'unified');
	let mode = $derived(ethernet.isDhcp ? 'Automatic' : 'Manual');
	let previousCarrier = $state('Viettel');
	$effect(() => {
		if (configuredProduct === 'bms' || configuredProduct === 'rts') profile = configuredProduct;
	});
	$effect(() => {
		if (selectedCarrier !== previousCarrier) {
			previousCarrier = selectedCarrier;
			chooseCarrier(selectedCarrier);
		}
	});
	onMount(()=>{if(configuredProduct==='bms'){if(hasBmsSession())void loadBmsPage();else{bmsNetworkError='Your session has expired. Please sign in again.';bmsModemError=bmsNetworkError}}else void loadRts();const timer=setInterval(()=>{if(rtsTab==='4g'&&(profile!=='bms'||hasBmsSession()))void refreshModemStatus();},5000);return()=>clearInterval(timer)});
	function toEthernet(item:NetworkConfig):RtsEthernetForm{return{isDhcp:item.isDhcp,ipAddress:item.ipAddress,subnetMask:item.subnetMask,gateway:item.gateway,dnsPrimary:item.dnsPrimary,dnsSecondary:item.dnsSecondary}}
	async function loadRts(){try{const [networks,status,modemConfig,modemState]=await Promise.all([getNetworkConfigs(),getNetworkActualStatus(),getModem4GConfig(),getModem4GStatus()]);rtsNetworks=networks;actualStatus=status;const current=networks.find((item)=>item.id===selectedRtsNetwork)??networks[0];if(current){selectedRtsNetwork=current.id;ethernet=toEthernet(current)}modem=modemConfig;modemStatus=modemState;rtsError='';}catch(cause){rtsError=cause instanceof Error?cause.message:'Unable to load RTS network configuration.'}}
	async function loadBmsPage(){await Promise.all([loadBmsNetworks(),loadBmsModem()])}
	async function loadBmsModem(){try{const [settings,status]=await Promise.all([getBmsModemConfig(),getBmsModemStatus()]);modem={enabled:settings.enabled,apn:settings.apn,username:settings.username,password:''};modemPasswordConfigured=settings.passwordConfigured;selectedCarrier=RTS_CARRIERS.find(item=>item.apn===settings.apn)?.name??'Custom';modemStatus=status;bmsModemError=''}catch(cause){bmsModemError=cause instanceof Error?cause.message:'Unable to load BMS 4G configuration.'}}
	async function refreshModemStatus(){try{modemStatus=profile==='bms'?await getBmsModemStatus():await getModem4GStatus()}catch(cause){const message=cause instanceof Error?cause.message:'Unable to refresh modem status.';if(profile==='bms')bmsModemError=message;else rtsError=message}}
	function selectRtsNetwork(id:'eth0'|'eth1'){selectedRtsNetwork=id;const item=rtsNetworks.find((network)=>network.id===id);if(item)ethernet=toEthernet(item)}
	function networkForm(item:BmsNetwork):BmsNetworkForm{return{id:item.id,name:item.name,interfaceName:item.interfaceName,available:item.available,connected:item.connected,status:item.status,error:item.error??undefined,ipAddress:item.ipAddress??'',subnetMask:item.subnetMask??'',gateway:item.gateway??'',dns:item.dns??'',mode:normalizeBmsNetworkMode(item.mode)}}
	async function loadBmsNetworks(){try{bmsNetworks=await listBmsNetworks();if(bmsNetworks.length)bms=networkForm(bmsNetworks.find((item)=>item.id===bms.id)??bmsNetworks[0]);bmsNetworkError=''}catch(cause){bmsNetworkError=cause instanceof Error?cause.message:'Unable to load BMS network configuration.'}}
	function selectBmsNetwork(id:string){const item=bmsNetworks.find((network)=>network.id===id);if(item)bms=networkForm(item)}

	function chooseProfile(value:ProductProfile){profile=value;rtsTab='ethernet';notice='';if(value==='bms'&&hasBmsSession())void loadBmsPage();else if(value==='rts')void loadRts()}
	function chooseCarrier(name:string){selectedCarrier=name;const carrier=RTS_CARRIERS.find((item)=>item.name===name);if(carrier&&name!=='Custom')modem.apn=carrier.apn}
	async function saveEthernet(){savingRts=true;rtsError='';try{const current=rtsNetworks.find((item)=>item.id===selectedRtsNetwork);await setNetworkConfig({id:selectedRtsNetwork,displayName:current?.displayName??selectedRtsNetwork,...ethernet});notice=`${current?.displayName??selectedRtsNetwork} saved successfully.`;await loadRts()}catch(cause){rtsError=cause instanceof Error?cause.message:'Unable to save RTS Ethernet configuration.'}finally{savingRts=false}}
	async function saveModem(){savingRts=true;rtsError='';bmsModemError='';try{const suppliedPassword=modem.password;if(profile==='bms')await updateBmsModemConfig({apn:modem.apn,username:modem.username,password:suppliedPassword});else await setModem4GConfig(modem);notice='4G/LTE configuration saved successfully.';if(profile==='bms'&&suppliedPassword)modemPasswordConfigured=true;modem.password='';await refreshModemStatus()}catch(cause){const message=cause instanceof Error?cause.message:'Unable to save 4G configuration.';if(profile==='bms')bmsModemError=message;else rtsError=message}finally{savingRts=false}}
	async function saveBms(){savingBms=true;bmsNetworkError='';try{const params=buildBmsNetworkUpdateParams(bms);if(hasBmsSession()){await updateBmsNetwork(params);await loadBmsNetworks()}notice=hasBmsSession()?'Network configuration saved with bms.tools.network.update.':'BMS payload is ready; authenticate to submit it.'}catch(cause){bmsNetworkError=cause instanceof Error?cause.message:'Unable to update BMS network configuration.'}finally{savingBms=false}}
</script>

<section class="page">
	<div class="page-head"><div><h2>Network</h2><p>Configure Ethernet and 4G/LTE connectivity for this appliance.</p></div></div>
	{#if showProfileSwitch}<div class="profile-switch"><button class:active={profile==='rts'} type="button" onclick={()=>chooseProfile('rts')}>RTS configuration</button><button class:active={profile==='bms'} type="button" onclick={()=>chooseProfile('bms')}>BMS configuration</button></div>{/if}
	<div class="tabs"><button class:active={rtsTab==='ethernet'} type="button" onclick={()=>rtsTab='ethernet'}>Ethernet</button><button class:active={rtsTab==='4g'} type="button" onclick={()=>rtsTab='4g'}>4G/LTE</button></div>
	{#if notice}<div class="notice"><Check size={16}/>{notice}</div>{/if}
	{#if rtsError && profile==='rts'}<p class="request-error">{rtsError}</p>{/if}
	{#if profile==='bms' && rtsTab==='ethernet' && bmsNetworkError}<p class="request-error">{bmsNetworkError}</p>{/if}
	{#if profile==='bms' && rtsTab==='4g' && bmsModemError}<p class="request-error">{bmsModemError}</p>{/if}

	{#if profile==='rts' && rtsTab==='ethernet'}
		<div class="network-picker" aria-label="RTS network interface">{#each rtsNetworks as network}<button class:active={selectedRtsNetwork===network.id} onclick={()=>selectRtsNetwork(network.id)}>{network.displayName}<small>{network.id} · {actualStatus[network.id]?.ip||network.ipAddress||'No IP'}</small></button>{/each}</div><section class="panel"><div class="panel-title"><span><EthernetPort size={20}/></span><div><h3>{rtsNetworks.find((item)=>item.id===selectedRtsNetwork)?.displayName??'Ethernet Interface'}</h3><p>{selectedRtsNetwork} · Actual IP: {actualStatus[selectedRtsNetwork]?.ip||'Not available'}</p></div></div><div class="interface-card"><div class="form-grid"><label>Mode<div class="mode-toggle"><button class:active={ethernet.isDhcp} type="button" onclick={()=>ethernet.isDhcp=true}>Automatic</button><button class:active={!ethernet.isDhcp} type="button" onclick={()=>ethernet.isDhcp=false}>Manual</button></div></label><label>IP Address<input disabled={ethernet.isDhcp} bind:value={ethernet.ipAddress} placeholder="192.168.x.x"/></label><label>Subnet Mask<input disabled={ethernet.isDhcp} bind:value={ethernet.subnetMask} placeholder="255.255.255.0"/></label><label>Gateway (Optional)<input disabled={ethernet.isDhcp} bind:value={ethernet.gateway} placeholder="192.168.x.1"/></label><label>Primary DNS<input disabled={ethernet.isDhcp} bind:value={ethernet.dnsPrimary} placeholder="8.8.8.8"/></label><label>Secondary DNS<input disabled={ethernet.isDhcp} bind:value={ethernet.dnsSecondary} placeholder="8.8.4.4"/></label></div><div class="actions"><span>Address assignment: {mode}</span><button class="primary" disabled={savingRts} type="button" onclick={saveEthernet}><Save size={16}/>{savingRts?'Saving…':'Save'}</button></div></div></section>
	{:else if rtsTab==='4g'}
		<div class="modem-layout"><section class="panel status"><div class="panel-title"><span><RadioTower size={20}/></span><div><h3>Modem Status</h3><p>Polled from modem4g0 every 5 seconds.</p></div><em class:online={modemStatus.status==='CONNECTED'}>{modemStatus.status}</em></div>{#if modemStatus.status==='NO_MODEM'}<div class="no-modem"><WifiOff size={24}/><strong>No 4G modem detected</strong><span>{modemStatus.lastError||'Please check the hardware connection.'}</span></div>{/if}<div class="status-list"><div><span>Signal Strength</span><strong>{modemStatus.signalStrength}%{modemStatus.signalDbm!=null?` · ${modemStatus.signalDbm} dBm`:''}</strong></div><div><span>Operator</span><strong>{modemStatus.operator}</strong></div><div><span>Connection Type</span><strong>{modemStatus.connectionType}</strong></div><div><span>IP Address</span><strong>{modemStatus.ipAddress}</strong></div><div><span>Modem Model</span><strong>{modemStatus.modemModel}</strong></div><div><span>IMEI</span><strong>{modemStatus.imei}</strong></div></div></section><section class="panel"><div class="panel-title"><span><RadioTower size={20}/></span><div><h3>4G/LTE Configuration</h3><p>Configuration from modem4g0.</p></div></div><div class="settings">{#if profile==='rts'}<label class="setting"><span>Enable 4G/LTE</span><button type="button" class:enabled={modem.enabled} class="switch" aria-pressed={modem.enabled} onclick={()=>modem.enabled=!modem.enabled}><i></i>{modem.enabled?'Enabled':'Disabled'}</button></label>{/if}<label>Carrier<FlatSelect bind:value={selectedCarrier} options={RTS_CARRIERS.map((item)=>item.name)} ariaLabel="Carrier" /></label><label>APN<input bind:value={modem.apn} readonly={selectedCarrier!=='Custom'} placeholder="e.g. v-internet"/></label><label>Username<input bind:value={modem.username} placeholder="Optional"/></label><label>Password<input type="password" bind:value={modem.password} placeholder={profile==='bms'&&modemPasswordConfigured?'Configured; leave blank to keep current password':'Optional'}/></label></div><div class="actions"><span></span><button class="primary" disabled={savingRts} type="button" onclick={saveModem}><Save size={16}/>{savingRts?'Saving…':'Save changes'}</button></div></section></div>
		<section class="reference"><h3>Common APNs Reference (Vietnam)</h3><div class="table-scroll"><table><thead><tr><th>Carrier</th><th>APN</th><th>Username</th><th>Password</th></tr></thead><tbody>{#each RTS_CARRIERS.filter((item)=>item.name!=='Custom') as carrier}<tr onclick={()=>chooseCarrier(carrier.name)}><td>{carrier.name}</td><td>{carrier.apn}</td><td>—</td><td>—</td></tr>{/each}</tbody></table></div></section>
	{:else}
		{#if bmsNetworks.length>1}<div class="network-picker" aria-label="BMS network interface">{#each bmsNetworks as network}<button class:active={bms.id===network.id} onclick={()=>selectBmsNetwork(network.id)}>{network.name}<small>{network.interfaceName||network.id}</small></button>{/each}</div>{/if}
		<section class="panel"><div class="panel-title"><span><EthernetPort size={20}/></span><div><h3>{bms.name}</h3><p>{bms.interfaceName || 'Interface not available'}</p></div><em class:online={bms.connected}>{bms.status}</em></div><div class="interface-card"><div class="form-grid"><label>Mode<div class="mode-toggle"><button class:active={bms.mode==='DHCP'} type="button" onclick={()=>bms.mode='DHCP'}>Automatic</button><button class:active={bms.mode==='STATIC'} type="button" onclick={()=>bms.mode='STATIC'}>Manual</button></div></label><label>IP Address<input disabled={bms.mode!=='STATIC'} bind:value={bms.ipAddress} placeholder="192.168.x.x"/></label><label>Subnet Mask<input disabled={bms.mode!=='STATIC'} bind:value={bms.subnetMask} placeholder="255.255.255.0"/></label><label>Gateway (Optional)<input disabled={bms.mode!=='STATIC'} bind:value={bms.gateway} placeholder="192.168.x.1"/></label><label>DNS<input disabled={bms.mode!=='STATIC'} bind:value={bms.dns} placeholder="8.8.8.8, 8.8.4.4"/></label></div>{#if bms.error}<p class="error">{bms.error}</p>{/if}<div class="actions"><span>Address assignment: {bms.mode==='DHCP'?'Automatic':bms.mode==='STATIC'?'Manual':'Unknown'}</span><button class="primary" type="button" disabled={savingBms || bms.mode==='UNKNOWN'} onclick={saveBms}><Save size={16}/>{savingBms?'Saving…':'Save'}</button></div></div></section>
	{/if}
</section>

<style>
	.page{animation:enter .18s ease-out}.page-head{margin-bottom:18px}.page-head h2{margin:0;color:#172b4d;font-size:24px;font-weight:500}.page-head p{margin:7px 0 0;color:#718096;font-size:16px}.profile-switch{display:inline-flex;margin-bottom:15px;padding:3px;border-radius:9px;background:#e9eef7}.profile-switch button{height:33px;padding:0 13px;border:0;border-radius:7px;color:#65738a;background:transparent;cursor:pointer;font:inherit;font-size:13px}.profile-switch button.active{color:#1749ad;background:#fff;box-shadow:0 1px 4px rgba(30,48,79,.1)}.tabs{display:flex;gap:5px;margin-bottom:16px;border-bottom:1px solid #e2e8f1}.tabs button{min-height:41px;padding:0 14px;border:0;border-bottom:2px solid transparent;color:#65738b;background:transparent;cursor:pointer;font:inherit;font-size:14px}.tabs button.active{border-color:#2454b6;color:#1d4ba7}.notice{display:flex;align-items:center;gap:7px;margin:0 0 14px;padding:10px 12px;border:1px solid #cae7d5;border-radius:8px;color:#28784e;background:#f2fbf5;font-size:13px}.panel,.reference{border:1px solid #e1e7f0;border-radius:12px;background:#fff}.panel-title{display:flex;align-items:center;gap:11px;padding:17px 19px;border-bottom:1px solid #edf0f4}.panel-title>span{display:grid;place-items:center;width:35px;height:35px;border-radius:9px;color:#2653ba;background:#eaf0ff}.panel-title h3,.reference h3{margin:0;color:#31415c;font-size:16px;font-weight:500}.panel-title p{margin:4px 0 0;color:#7b879a;font-size:13px}.panel-title em{margin-left:auto;padding:5px 8px;border-radius:12px;color:#ad382f;background:#fff0ee;font-size:11px;font-style:normal}.panel-title em.online{color:#27764d;background:#eef9f2}.interface-card{padding:18px 19px}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.form-grid label,.settings>label{display:grid;gap:6px;color:#536078;font-size:13px}.form-grid input,.settings input{width:100%;height:39px;padding:0 11px;border:1px solid #d7dfeb;border-radius:7px;color:#273853;background:#fff;font:inherit;font-size:14px}.form-grid input:disabled{color:#7f8a9d;background:#f5f7fa}.mode-toggle{display:flex;height:39px;padding:3px;border-radius:8px;background:#eef2f8}.mode-toggle button{flex:1;border:0;border-radius:6px;color:#68768c;background:transparent;cursor:pointer;font:inherit;font-size:13px}.mode-toggle button.active{color:#184aa8;background:#fff;box-shadow:0 1px 4px rgba(31,50,80,.09)}.actions{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-top:18px;padding-top:14px;border-top:1px solid #edf0f4}.actions span{color:#8792a4;font-size:12px}.primary{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:38px;padding:0 14px;border:0;border-radius:8px;color:#fff;background:#1749ad;cursor:pointer;font:inherit;font-size:14px}.modem-layout{display:grid;grid-template-columns:minmax(0,.85fr) minmax(0,1.15fr);gap:16px}.no-modem{display:grid;margin:17px;padding:20px;place-items:center;border-radius:9px;color:#8e554f;background:#fff5f3;text-align:center}.no-modem strong{margin-top:8px;font-weight:500}.no-modem span{margin-top:4px;color:#9a6b67;font-size:12px}.status-list{padding:0 18px 17px}.status-list div{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #eef1f5;color:#6e7a8e;font-size:13px}.status-list strong{color:#35445e;font-weight:500}.settings{display:grid;gap:13px;padding:18px}.setting{grid-template-columns:1fr auto!important;align-items:center}.switch{display:inline-flex;align-items:center;gap:7px;height:32px;padding:0 9px;border:1px solid #d7dfeb;border-radius:16px;color:#77849a;background:#fff;cursor:pointer;font:inherit;font-size:12px}.switch i{width:8px;height:8px;border-radius:50%;background:#9ba6b5}.switch.enabled{border-color:#b9dfc9;color:#24764d;background:#f1fbf5}.switch.enabled i{background:#2eae68}.panel>.actions{margin:0;padding:12px 18px}.reference{margin-top:16px;overflow:hidden}.reference h3{padding:15px 18px;border-bottom:1px solid #edf0f4}.table-scroll{overflow-x:auto}table{width:100%;min-width:550px;border-collapse:collapse}th,td{padding:11px 16px;border-bottom:1px solid #edf1f6;color:#56657c;font-size:13px;text-align:left}th{color:#7c8899;background:#f8faff;font-size:11px;font-weight:500;text-transform:uppercase}tbody tr{cursor:pointer}tbody tr:hover{background:#fafcff}.error{color:#c5281c}@keyframes enter{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}@media(max-width:950px){.form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.modem-layout{grid-template-columns:1fr}}@media(max-width:650px){.form-grid{grid-template-columns:1fr}.profile-switch{display:flex}.profile-switch button{flex:1}.actions{align-items:flex-end;flex-direction:column}.actions .primary{width:100%}}
	.network-picker{display:flex;gap:7px;margin-bottom:12px;overflow-x:auto}.network-picker button{min-width:135px;padding:9px 11px;border:1px solid #dce3ed;border-radius:8px;color:#536078;background:#fff;font:inherit;text-align:left;cursor:pointer}.network-picker button.active{border-color:#9db8ed;color:#1749ad;background:#f2f6ff}.network-picker small{display:block;margin-top:3px;color:#8792a4}.request-error{padding:10px 12px;border:1px solid #f3cac6;border-radius:8px;color:#b42318;background:#fff1f0;font-size:13px}.primary:disabled{opacity:.55;cursor:wait}
</style>
